// Общие шаги для Billing & Subscription (#b20fe6 «Cancels on» у доп. компании, #feb50f валюта Checkout; план specs/billing.md).
// Окружение: Pre-Prod, preprod-ttp (TTP Test Locks, Owner), EN. Оплата не выполняется: Checkout только открывается и закрывается.
// Не сверено с сайтом при записи (правило проекта — тесты только пишутся): путь на Billing — через меню аккаунта (аватар → «Billing & Subscription»);
// разметка строк таблицы Subscription — по скриншоту b20fe6-billing-desktop.png (Product / Plan / Price / Billing cycle / Next billing date).
import { expect, Locator, Page } from '@playwright/test';
import { pp, ROLE } from '../pricebook/pricebook-helpers';

export { ROLE, pp };

export async function setEnglish(page: Page) {
  await page.addInitScript(() => { try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ } });
}

/** Home → аватар (Owner / Admin) → «Billing & Subscription». */
export async function openBilling(page: Page) {
  await setEnglish(page);
  await page.goto(pp('/dashboard'));
  const avatar = page.getByRole('button').filter({ hasText: /Owner|Admin/ }).last();
  await expect(avatar).toBeVisible({ timeout: 30_000 });
  await avatar.click();
  await page.getByRole('menuitem', { name: /Billing/ }).or(page.getByRole('link', { name: /Billing/ })).first().click();
  await expect(page.getByRole('heading', { name: 'Billing & Subscription' })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText('Subscription', { exact: true }).first()).toBeVisible();
}

/** Строка таблицы Subscription по названию продукта («Techory», «Extra companies»). */
export function subscriptionRow(page: Page, product: string): Locator {
  return page.getByRole('row').filter({ has: page.getByText(product, { exact: true }) });
}

// ---------- #2185f2 «Cancel subscription» (добавлено 2026-11-17; не сверено с сайтом при записи) ----------
// Аккаунт preprod-a (Starter Tech, trial, карта 4242). Отмена НЕ подтверждается: только окно и «Keep my plan» в окне.
export const SUB_ROLE = 'preprod-a';

/** Billing прямым адресом (/BillingSubscription), язык — до загрузки страницы. */
export async function openBillingDirect(page: Page, lang: 'en' | 'he' = 'en') {
  await page.addInitScript((l) => { try { window.localStorage.setItem('preferred-language', l); } catch { /* ignore */ } }, lang);
  await page.goto(pp('/BillingSubscription'));
  await expect(page.getByRole('heading', { name: lang === 'en' ? 'Billing & Subscription' : 'חיוב ומינוי' })).toBeVisible({ timeout: 30_000 });
}

export const cancelSubscriptionButton = (page: Page, name: string | RegExp = 'Cancel subscription'): Locator =>
  page.getByRole('button', { name, exact: typeof name === 'string' });

/** Окно подтверждения отмены (по заголовку «Cancel your Techory subscription?» / иврит «…ל-Techory?»). */
export const cancelDialog = (page: Page, title: string | RegExp): Locator =>
  page.getByRole('dialog').or(page.getByRole('alertdialog')).filter({ hasText: title });
